54207a24-736b-470b-a2f3-6ab0041b327d	file-guard	guard	File Guard	Intercepts file artifacts produced by A2A agents, quarantines them, and runs the configured processor pipeline before delivery.	{"mode": "block", "enabled": false, "processors": {"av_scan": {"enabled": true, "max_bytes": 5242880, "block_on_infected": true}, "audit_capture": {"enabled": true}}, "allowed_types": [], "blocked_types": ["exe", "sh", "bat", "ps1", "cmd"], "notify_on_fail": true, "max_file_size_mb": 5}	t	t	2026-09-15 14:23:51.659077+00	2026-09-15 14:23:51.659077+00	builtin	1	builtin	published		🛡️	#f59e0b	rgba(245,158,11,0.08)	{"max_in": 1, "min_in": 1, "max_out": 1, "min_out": 1}	\N	\N	[{"key": "enabled", "type": "bool", "example": "true", "required": true, "description": "Whether File Guard is active on this wiring."}, {"key": "mode", "type": "string", "example": "block", "options": ["block", "warn"], "required": true, "description": "\\"block\\" quarantines infected files; \\"warn\\" logs only and still delivers the file."}, {"key": "max_file_size_mb", "type": "int", "example": "5", "required": false, "description": "Maximum accepted file size in megabytes."}, {"key": "allowed_types", "type": "array", "example": "[\\"pdf\\", \\"png\\", \\"csv\\"]", "required": false, "description": "Comma-separated file extensions to allow. Empty means all types are allowed."}, {"key": "blocked_types", "type": "array", "example": "[\\"exe\\", \\"sh\\", \\"bat\\"]", "required": false, "description": "Comma-separated file extensions to always reject."}, {"key": "notify_on_fail", "type": "bool", "example": "true", "required": false, "description": "Send a notification when a file is blocked or flagged."}]
2044e808-3083-427d-a0d4-1cefc67ab8dc	prompt_inject	guard	Prompt-Injection Guard	Detects known prompt-injection phrasing (instruction-override attempts, role-override attempts, delimiter escapes) in text produced by an llm or agent node.	{"mode": "block", "enabled": false, "direction": "output", "sensitivity": "medium"}	t	t	2026-09-27 12:29:14.906202+00	2026-09-27 12:29:14.906202+00	them.builtin	1	builtin	published		\N	\N	\N	{"max_in": 1, "min_in": 1, "max_out": 1, "min_out": 1}	\N	\N	[{"key": "enabled", "type": "bool", "example": "true", "required": true, "description": "Whether Prompt-Injection Guard is active on this wiring."}, {"key": "mode", "type": "string", "example": "block", "options": ["block", "warn"], "required": true, "description": "\\"block\\" rejects text matching a known injection pattern; \\"warn\\" logs only."}, {"key": "sensitivity", "type": "string", "example": "medium", "options": ["low", "medium", "high"], "required": false, "description": "Higher sensitivity checks more, less-certain patterns -- more false positives, fewer misses."}, {"key": "direction", "type": "string", "example": "output", "options": ["output", "both"], "required": false, "description": "\\"output\\" scans what the node produced (default); \\"both\\" also scans the incoming prompt before it is sent."}]
